(14, '7b6d6d61-31b6-11f0-9444-00e04c364c8c', '{\"name\":\"Delivery Register\",\"uuid\":\"3a9299e5-25b6-4489-9878-0cdfba06fba1\",\"processor\":\"EncounterFormProcessor\",\"version\":\"1.1\",\"published\":true,\"retired\":false,\"description\":\"Delivery Register - CCFN\",\"pages\":[{\"label\":\"Delivery Information\",\"sections\":[{\"label\":\"Delivery Information\",\"questions\":[{\"label\":\"Date of delivery\",\"type\":\"encounterDatetime\",\"required\":true,\"id\":\"dateOfDelivery\",\"datePickerFormat\":\"both\",\"questionOptions\":{\"rendering\":\"date\"},\"validators\":[{\"type\":\"date\",\"allowFutureDates\":\"false\"}]},{\"label\":\"Time of HIV diagnosis:\",\"type\":\"obs\",\"id\":\"timeofHIVdiagnosis\",\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"164851AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"answers\":[{\"concept\":\"c67dc265-75d5-493a-b142-8bf7be6d7fa7\",\"label\":\"ANC\"},{\"concept\":\"77e710b5-ec47-4b0c-8e0b-de5837a48aae\",\"label\":\"L&D Booked\"},{\"concept\":\"820b93f4-5caa-4acc-8167-a479ac68ee4e\",\"label\":\"L&D Unbooked\"},{\"concept\":\"5a6f8782-f3f0-46a9-b224-90770f57807a\",\"label\":\"Previously known HIV+\"}]}},{\"label\":\"GA (wks) at birth\",\"id\":\"gestational_age\",\"questionOptions\":{\"rendering\":\"number\",\"concept\":\"1409AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"max\":\"50\",\"min\":\"1\",\"step\":1,\"disallowDecimals\":true},\"type\":\"obs\",\"validators\":[{\"type\":\"js_expression\",\"failsWhenExpression\":\"gestational_age && (gestational_age < 1 || gestational_age > 50 || gestational_age % 1 !== 0)\",\"message\":\"Gestational age must be a whole number between 1 and 50 weeks.\"}]},{\"label\":\"Hepatitis B Status\",\"type\":\"obs\",\"id\":\"hep_B_status\",\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"159430AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"answers\":[{\"concept\":\"703AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Positive\"},{\"concept\":\"664AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Negative\"}]}},{\"label\":\"Hepatitis C Status\",\"type\":\"obs\",\"id\":\"hep_c_status\",\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"161471AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"answers\":[{\"concept\":\"703AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Positive\"},{\"concept\":\"664AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Negative\"}]}},{\"label\":\"Currently taking ART\",\"type\":\"obs\",\"id\":\"currentlytakingART\",\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"160119AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"answers\":[{\"concept\":\"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Yes\"},{\"concept\":\"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"No\"}]}},{\"label\":\"ART started in labour & delivery ward\",\"type\":\"obs\",\"id\":\"aRT_started_in_labour\",\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"1b848d1d-74b7-4dad-9d8f-db2354426f76\",\"answers\":[{\"concept\":\"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Yes\"},{\"concept\":\"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"No\"}]}},{\"label\":\"Rupture of Membrane delivery interval\",\"type\":\"obs\",\"id\":\"rom_delivery_interval\",\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"f6cf0fd3-592e-4849-a138-cf02ab111179\",\"answers\":[{\"concept\":\"7b845369-cb72-4100-a907-f472cfd1d86d\",\"label\":\"<4hrs\"},{\"concept\":\"b54e57fe-c562-4d9c-9784-ec6975331d2b\",\"label\":\">=4hrs\"}]}},{\"label\":\"Mode of delivery\",\"type\":\"obs\",\"id\":\"mode_of_delivery\",\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"5630AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"answers\":[{\"concept\":\"1170AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Vaginal\"},{\"concept\":\"1171AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Elective CS\"},{\"concept\":\"159739AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Emergency CS\"}]}},{\"label\":\"Episiotomy done?\",\"type\":\"obs\",\"required\":false,\"id\":\"episiotomyDone\",\"hide\":{\"hideWhenExpression\":\"isEmpty(mode_of_deliv