(23, 'dce3b2a5-3166-11f0-b8e6-0a0027000011', '{\"name\":\"Maternal Cohort Register\",\"uuid\":\"5f217cca-75c7-49be-a559-f9714d3d0bd7\",\"processor\":\"EncounterFormProcessor\",\"pages\":[{\"label\":\"Maternal Cohort Register\",\"sections\":[{\"label\":\"Maternal Cohort Register\",\"questions\":[{\"label\":\"Visit Date\",\"type\":\"encounterDatetime\",\"required\":true,\"id\":\"visitDate\",\"datePickerFormat\":\"calendar\",\"questionOptions\":{\"rendering\":\"date\"},\"validators\":[{\"type\":\"date\",\"allowFutureDates\":\"false\"}]},{\"label\":\"Timing of Mother\'s ART Initiation:\",\"type\":\"obs\",\"id\":\"Timing_of_Mother_ART_Initiation\",\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"be5a8c79-d4a6-4b7c-8cec-872839b8342a\",\"answers\":[{\"concept\":\"6013b3bd-f99b-4107-9eb6-64e4bcf7232b\",\"label\":\"Period Prior to Pregnancy\"},{\"concept\":\"2f381528-2572-408d-b986-6a6ba45ef43d\",\"label\":\"Initiated ART during pregnancy < 36 weeks gestation period\"},{\"concept\":\"5de4104d-8a21-48eb-8410-96a88c910426\",\"label\":\"Initiated ART during pregnancy >= 36 weeks gestation period\"},{\"concept\":\"164850AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Initiated ART at Labour and Delivery\"},{\"concept\":\"1180AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Initiated ART after delivery (post-partum)\"},{\"concept\":\"1107AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"None\"}]}},{\"label\":\"TB Status:\",\"type\":\"obs\",\"id\":\"Tuberculosis_disease_status\",\"required\":true,\"questionOptions\":{\"rendering\":\"select\",\"concept\":\"1659AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"answers\":[{\"concept\":\"1660AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"No Signs or Symptoms of TB, not on IPT\"},{\"concept\":\"142177AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Presumptive TB\"},{\"concept\":\"1661AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"TB Diagnosed (Confirmed)\"},{\"concept\":\"1662AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Currently On Treatment\"}]