(35, '6ad1ffa3-74d9-43e9-ae3a-e033fcb88b0d','{\"name\":\"Specimen Examination Request Form\",\"description\":\"Specimen Examination Request Form\",\"version\":\"1.0\",\"published\":true,\"retired\":false,\"processor\":\"EncounterFormProcessor\",\"encounterType\":\"27e834a7-a8bb-4f9d-8082-6400ad7a239c\",\"referencedForms\":[],\"uuid\":\"d163707d-5ce7-4913-b62f-ba6d261daca2\",\"pages\":[{\"label\":\"Starter page\",\"sections\":[{\"label\":\"Starter section\",\"isExpanded\":true,\"questions\":[{\"label\":\"Date of Specimen Collection\",\"type\":\"obs\",\"required\":false,\"id\":\"date_of_specimen_collection\",\"datePickerFormat\":\"calendar\",\"questionOptions\":{\"rendering\":\"date\",\"concept\":\"159951AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\"}},{\"label\":\"Specimen Identification N0:\",\"type\":\"obs\",\"id\":\"specimen_identification_no\",\"questionOptions\":{\"concept\":\"7add9fa7-8104-4ce9-b7d6-8e9675d6f954\",\"rendering\":\"number\"}},{\"label\":\"LGA/TB N0:\",\"type\":\"obs\",\"id\":\"lga_tb_no\",\"questionOptions\":{\"concept\":\"b7dfe666-7a00-42f8-bb7f-8f81f315488c\",\"rendering\":\"text\"}},{\"label\":\"Type of Presumptive TB(Tick One Only)\",\"type\":\"obs\",\"id\":\"type_of_presumptive_tb\",\"questionOptions\":{\"concept\":\"6c6811f4-a656-412d-ab16-2047c953fd8e\",\"rendering\":\"select\",\"answers\":[{\"concept\":\"4df9c805-cabe-4ae3-9d1f-1ba8c3995429\",\"label\":\"DS-TB\"},{\"concept\":\"7f56b700-410b-4099-9170-9c4603a19cd7\",\"label\":\"DR-TB\"}]}},{\"label\":\"Site of Disease\",\"type\":\"obs\",\"id\":\"site_of_disease\",\"questionOptions\":{\"concept\":\"0ece789e-451b-49fb-8b25-49073fb0c6db\",\"rendering\":\"select\",\"answers\":[{\"concept\":\"156204AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Extra Pulmonary TB\"},{\"concept\":\"831AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\"label\":\"Pulmonary TB\"}]}},{\"label\":\"Is The Patient a Health Care Worker?\",\"type\":\"obs\",\"id\":\"is_the_patient_a_health_care_worker\",\"questionOptions\":{\"concept\":\"5fb4a017-51